:root {
  color-scheme: dark;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  color: #edf4ef;
  background: #172b35;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  --ink: #edf4ef;
  --muted: #a2b8b5;
  --mint: #a8edbd;
  --panel: #203b44;
  --line: #35555b;
}

* { box-sizing: border-box; }
body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  padding: 32px 16px;
  display: grid;
  place-items: center;
  background-color: #172b35;
  background-image: radial-gradient(#34515a 1px, transparent 1px);
  background-size: 22px 22px;
}
button { font: inherit; }
.meter {
  width: min(100%, 420px);
  padding: 30px 28px 22px;
  border: 1px solid #426168;
  border-radius: 18px;
  background: #1b343e;
  box-shadow: 0 18px 55px #0c1d24aa, inset 0 1px #ffffff0c;
}
.header { text-align: center; }
.pixel-car {
  position: relative;
  width: 64px;
  height: 30px;
  margin: 0 auto 18px;
  background: var(--mint);
  clip-path: polygon(12% 34%, 29% 34%, 42% 0, 75% 0, 91% 34%, 100% 40%, 100% 86%, 0 86%, 0 51%);
}
.pixel-car::before {
  content: "";
  position: absolute;
  inset: 4px 19px 13px 30px;
  background: #203b44;
  clip-path: polygon(29% 0, 86% 0, 100% 100%, 0 100%);
}
.pixel-car span::before, .pixel-car span::after {
  content: "";
  position: absolute;
  bottom: 0;
  width: 12px;
  height: 12px;
  border: 3px solid #1b343e;
  border-radius: 50%;
  background: #a8edbd;
}
.pixel-car span::before { left: 10px; }
.pixel-car span::after { right: 10px; }
.eyebrow {
  margin: 0;
  color: var(--mint);
  font-size: .75rem;
  font-weight: 750;
  letter-spacing: .16em;
}
h1 { margin: 7px 0 2px; font-size: 2rem; line-height: 1.2; letter-spacing: -.04em; }
.subtitle { margin: 0; color: var(--muted); }
.fare-panel {
  margin: 27px 0 18px;
  padding: 20px 16px 17px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: #142a33;
  text-align: center;
}
.fare { margin: 4px 0 0; color: var(--mint); font-size: 3.5rem; font-weight: 760; line-height: 1.1; letter-spacing: -.055em; font-variant-numeric: tabular-nums; }
.currency { margin-right: 2px; font-size: 2rem; vertical-align: .4em; }
.base-note { margin: 5px 0 0; color: var(--muted); font-size: .875rem; }
.trip-stats { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.stat { display: grid; grid-template-columns: 28px 1fr; align-items: center; column-gap: 7px; padding: 13px; border: 1px solid var(--line); border-radius: 10px; background: var(--panel); }
.stat-icon { grid-row: span 2; color: var(--mint); font-size: 1.35rem; font-weight: 700; text-align: center; }
.clock-icon { font-size: 1.6rem; }
.stat-label { color: var(--muted); font-size: .875rem; }
.stat strong { font-size: 1.25rem; font-variant-numeric: tabular-nums; }
.stat small { color: var(--muted); font-size: .875rem; font-weight: 500; }
.controls { display: grid; gap: 10px; margin-top: 18px; }
.action {
  display: grid;
  grid-template-columns: 28px 1fr auto;
  align-items: center;
  gap: 9px;
  width: 100%;
  min-height: 58px;
  padding: 10px 14px;
  border: 1px solid #426168;
  border-radius: 10px;
  color: var(--ink);
  background: #29474f;
  cursor: pointer;
  text-align: left;
  transition: background .15s ease, border-color .15s ease, transform .12s ease;
}
.action:hover { border-color: var(--mint); background: #31545a; }
.action:active { transform: translateY(2px); background: #203b44; }
.button-symbol { color: var(--mint); font-size: 1.5rem; font-weight: 600; text-align: center; }
.rate { color: var(--muted); font-size: .8125rem; }
.reset {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  min-height: 46px;
  margin-top: 12px;
  border: 1px solid transparent;
  border-radius: 9px;
  color: var(--muted);
  background: transparent;
  cursor: pointer;
  transition: color .15s ease, background .15s ease, transform .12s ease;
}
.reset:hover { color: var(--ink); background: #29474f; }
.reset:active { transform: translateY(2px); }
button:focus-visible { outline: 3px solid var(--mint); outline-offset: 3px; }
footer { margin-top: 15px; color: #829d9c; font-size: .6875rem; font-weight: 700; letter-spacing: .14em; text-align: center; }
footer span { padding: 0 5px; color: var(--mint); }

@media (max-width: 390px) {
  .meter { padding: 25px 20px 19px; }
  .rate { font-size: .75rem; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; transition-duration: .01ms !important; }
}

"use strict";

const distanceDisplay = document.getElementById("distance");
const waitingDisplay = document.getElementById("waiting");
const fareDisplay = document.getElementById("fare");

let distance = 0;
let waiting = 0;

function render() {
  distanceDisplay.textContent = String(distance);
  waitingDisplay.textContent = String(waiting);
  const fare = 3 + distance * 1.5 + waiting * 0.4;
  fareDisplay.textContent = fare.toFixed(2);
}

document.getElementById("add-km").addEventListener("click", () => {
  distance += 1;
  render();
});

document.getElementById("add-minute").addEventListener("click", () => {
  waiting += 1;
  render();
});

document.getElementById("new-trip").addEventListener("click", () => {
  distance = 0;
  waiting = 0;
  render();
});

render();
